71	  function fmtLocalTime(iso) {
72	    var d = new Date(iso);
73	    if (isNaN(d.getTime())) return "";
74	    var pad = function (n) { return (n < 10 ? "0" : "") + n; };
75	    var local = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
76	      " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
77	    var off = -d.getTimezoneOffset();
78	    var sign = off >= 0 ? "+" : "-";
79	    var abs = Math.abs(off);
80	    var tz = "UTC" + sign + Math.floor(abs / 60) + (abs % 60 ? ":" + pad(abs % 60) : "");
81	    return local + "（访问者本地时间，" + tz + "）";
