121	  /* axis labels wrap only at ：、与、（ and spaces — ASCII words (WAL / MVCC /
122	     3NF …) are never split. ： and （ are hard breaks; a line that would still
123	     overflow backtracks to the last soft break (after 与 or a space). */
124	  function wrapAxisLabel(name, maxLine) {
125	    var s = String(name == null ? "" : name);
126	    if (!s) return "";
127	    var tokens = s.match(/[A-Za-z0-9]+|[^A-Za-z0-9]/g) || [];
128	    var widthOf = function (t) {
129	      var w = 0;
130	      for (var i = 0; i < t.length; i++)
131	        w += t.charAt(i) === " " ? 0.3 : (t.charCodeAt(i) < 128 ? 0.55 : 1);
132	      return w;
133	    };
134	    var lines = [];
135	    var cur = "";
136	    var curW = 0;
137	    var mark = -1; /* index in cur where a soft break is allowed */
138	    var prevTok = "";
139	    tokens.forEach(function (tok) {
140	      if (tok === " ") {
141	        if (cur !== "") { cur += " "; curW += 0.3; mark = cur.length - 1; }
142	        return;
143	      }
144	      var w = widthOf(tok);
145	      if (cur !== "" && (tok === "（" || prevTok === "：")) {
146	        lines.push(cur);
147	        cur = ""; curW = 0; mark = -1;
148	      } else if (cur !== "" && curW + w > maxLine) {
149	        if (mark > 0) {
150	          lines.push(cur.slice(0, mark));
151	          cur = cur.slice(mark).replace(/^ /, "");
152	          curW = widthOf(cur);
153	          mark = -1;
154	        } /* else: no allowed break point — the container measurement is the real limit */
155	      }
156	      cur += tok;
157	      curW += w;
158	      if (tok === "：" || tok === "与") mark = cur.length;
159	      prevTok = tok;
160	    });
161	    if (cur !== "" || lines.length === 0) lines.push(cur);
162	    return lines.join("\n");
163	  }
